import re

_POSTCODE = re.compile(r"\b\d{4}\s?[A-Z]{2}\b")


def parse_address(text):
    m = _POSTCODE.search(text)
    return {"street": text[: m.start()].strip(", ") if m else text, "postcode": m.group(0) if m else None}

from functools import lru_cache

from ._table import _TABLE
from .parse import parse_address


@lru_cache(maxsize=4096)
def lookup(postcode):
    return _TABLE.get(postcode.replace(" ", ""))


def geocode(text):
    return lookup(parse_address(text)["postcode"])
